import React from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';
import { 
  FaHtml5, 
  FaCss3Alt, 
  FaJs, 
  FaPython, 
  FaBootstrap, 
  FaGithub,
  FaReact,
  FaNodeJs
} from 'react-icons/fa';

const SkillsSection = styled.section`
  padding: var(--spacing-3xl) 0;
  background-color: var(--bg-primary);
`;

const Container = styled.div`
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
`;

const SectionHeader = styled(motion.div)`
  text-align: center;
  margin-bottom: var(--spacing-3xl);
`;

const SectionTitle = styled.h2`
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: var(--spacing-md);
  font-family: var(--font-secondary);
`;

const SectionSubtitle = styled.p`
  font-size: 1.2rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.7;
`;

const SkillsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: var(--spacing-xl);
`;

const SkillCard = styled(motion.div)`
  background-color: var(--bg-secondary);
  padding: var(--spacing-xl);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-color);
  transition: all var(--transition-fast);

  &:hover {
    transform: translateY(-5px);
    box-shadow: var(--shadow-lg);
  }
`;

const SkillHeader = styled.div`
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-lg);
`;

const SkillIcon = styled.div`
  width: 50px;
  height: 50px;
  border-radius: var(--radius-lg);
  background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 1.5rem;
`;

const SkillInfo = styled.div`
  flex: 1;
`;

const SkillName = styled.h3`
  font-size: 1.2rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: var(--spacing-xs);
`;

const SkillLevel = styled.p`
  font-size: 0.9rem;
  color: var(--text-muted);
`;

const ProgressContainer = styled.div`
  width: 100%;
  height: 8px;
  background-color: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  overflow: hidden;
  margin-bottom: var(--spacing-sm);
`;

const ProgressBar = styled(motion.div)`
  height: 100%;
  background: linear-gradient(90deg, var(--primary-color), var(--secondary-color));
  border-radius: var(--radius-sm);
  transform-origin: left;
`;

const ProgressText = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.9rem;
  color: var(--text-muted);
`;

const Skills = () => {
  const [ref, inView] = useInView({
    threshold: 0.3,
    triggerOnce: true
  });

  const skills = [
    {
      name: "Networking (CCNA)",
      level: 75,
      description: "TCP/IP, OSI model, subnetting, VLANs, routing (OSPF), Packet Tracer",
      icon: FaHtml5,
      color: "#E34F26"
    },
    {
      name: "Cybersecurity Tools",
      level: 70,
      description: "Wireshark, Metasploit, Nmap, basic SQL injection analysis",
      icon: FaCss3Alt,
      color: "#1572B6"
    },
    {
      name: "Web Technologies",
      level: 80,
      description: "HTML5, CSS3, JavaScript, PHP, MySQL, Bootstrap",
      icon: FaJs,
      color: "#F7DF1E"
    },
    {
      name: "Programming & Scripting",
      level: 65,
      description: "Python scripting, SQL queries, problem-solving with code",
      icon: FaPython,
      color: "#3776AB"
    },
    {
      name: "Operating Systems",
      level: 70,
      description: "Linux (Kali, Ubuntu, Fedora) and Windows Server administration",
      icon: FaBootstrap,
      color: "#7952B3"
    },
    {
      name: "Hardware & Troubleshooting",
      level: 60,
      description: "PC assembly, diagnostics, preventive maintenance and replacement",
      icon: FaGithub,
      color: "#181717"
    }
  ];

  return (
    <SkillsSection id="skills" ref={ref}>
      <Container>
        <SectionHeader
          initial={{ opacity: 0, y: 30 }}
          animate={inView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.6 }}
        >
          <SectionTitle>My Skills</SectionTitle>
          <SectionSubtitle>
            This reflects my CV: networking and cybersecurity, system administration, and modern
            web development with HTML, CSS, JavaScript, PHP, MySQL, and Python.
          </SectionSubtitle>
        </SectionHeader>

        <SkillsGrid>
          {skills.map((skill, index) => (
            <SkillCard
              key={skill.name}
              initial={{ opacity: 0, y: 30 }}
              animate={inView ? { opacity: 1, y: 0 } : {}}
              transition={{ duration: 0.6, delay: index * 0.1 }}
              whileHover={{ scale: 1.02 }}
            >
              <SkillHeader>
                <SkillIcon style={{ background: `linear-gradient(135deg, ${skill.color}, var(--secondary-color))` }}>
                  <skill.icon />
                </SkillIcon>
                <SkillInfo>
                  <SkillName>{skill.name}</SkillName>
                  <SkillLevel>{skill.description}</SkillLevel>
                </SkillInfo>
              </SkillHeader>

              <ProgressContainer>
                <ProgressBar
                  initial={{ scaleX: 0 }}
                  animate={inView ? { scaleX: skill.level / 100 } : { scaleX: 0 }}
                  transition={{ duration: 1, delay: 0.5 + index * 0.1 }}
                />
              </ProgressContainer>

              <ProgressText>
                <span>Proficiency</span>
                <span>{skill.level}%</span>
              </ProgressText>
            </SkillCard>
          ))}
        </SkillsGrid>
      </Container>
    </SkillsSection>
  );
};

export default Skills;
